(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-462":{scenario:{company:"Chỉ Vàng Garment",supervisor:{name:"Đỗ Thị Lan Anh",role:{vi:"Trưởng nhóm Lương & Phúc lợi",en:"Compensation & Benefits Lead"}},ref_code:"PAY-1125",title:{vi:"Đúng tiền lương đóng. Đúng số khấu trừ. Đúng luật bảo hiểm.",en:"Right contribution wage. Right deduction. Insurance compliant."},brief:{vi:"Đây là tình huống đào tạo. Bạn kiểm tra bảng lương tháng 11 PAY-1125 của chị Mai, tổ trưởng chuyền may: lương theo chức danh 12.000.000 đồng, phụ cấp trách nhiệm tổ trưởng 1.500.000 đồng, tiền ăn giữa ca 730.000 đồng, hỗ trợ xăng xe 500.000 đồng. Tỷ lệ người lao động đóng BHXH, BHYT, BHTN trong bài mô phỏng là 10.5%. Đối chiếu bảng lương nháp với hồ sơ đã duyệt, sửa phân loại phụ cấp trách nhiệm và số tiền khấu trừ bảo hiểm, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are checking November payroll PAY-1125 for Ms Mai, a sewing line leader: job-title wage VND 12,000,000, team leader responsibility allowance VND 1,500,000, shift meal allowance VND 730,000 and fuel support VND 500,000. The employee rate for social, health and unemployment insurance in this simulation is 10.5%. Compare the draft payroll with the approved file, correct the classification of the responsibility allowance and the insurance deduction, then write an evidence-based report."},reference_title:{vi:"Bảng phân loại thu nhập & hồ sơ mức đóng đã duyệt · PAY-1125",en:"Approved income classification & contribution file · PAY-1125"},fields:[{id:"ALLOW_CLASS",label:{vi:"Phân loại phụ cấp trách nhiệm tổ trưởng",en:"Classification of the team leader allowance"},initial:"SI-EXCL",expected:"SI-INCL",choices:["SI-INCL","SI-EXCL","PIT-EXEMPT"],reference:"Bảng phân loại thu nhập đóng BHXH",hint:{vi:"Phụ cấp lương gắn với chức danh, trách nhiệm công việc thuộc tiền lương đóng BHXH; tiền ăn giữa ca, xăng xe thì không.",en:"Wage allowances tied to the job title or responsibilities count toward the contribution wage; meal and fuel support do not."}},{id:"SI_DEDUCT",label:{vi:"Khấu trừ bảo hiểm của người lao động (đồng)",en:"Employee insurance deduction (VND)"},initial:"1260000",expected:"1417500",reference:"Hồ sơ đăng ký mức đóng BHXH",ref_value:{vi:"Lương chức danh 12.000.000; phụ cấp trách nhiệm 1.500.000; tỷ lệ người lao động 10.5%",en:"Job-title wage 12,000,000; responsibility allowance 1,500,000; employee rate 10.5%"},hint:{vi:"Bản nháp chỉ nhân tỷ lệ với lương chức danh; tiền lương đóng phải gồm cả phụ cấp lương.",en:"The draft applied the rate to the job-title wage only; the contribution wage must include wage allowances."}}],sop32:{vi:"Tiền lương đóng BHXH = lương chức danh + các phụ cấp lương mã SI-INCL; không gồm khoản SI-EXCL như tiền ăn giữa ca, hỗ trợ xăng xe. Khấu trừ = tiền lương đóng x 10.5% (tỷ lệ mô phỏng).",en:"Contribution wage = job-title wage + wage allowances coded SI-INCL; SI-EXCL items such as shift meals and fuel support are excluded. Deduction = contribution wage x 10.5% (simulated rate)."},context:{label:"BẢNG LƯƠNG NHÁP / PAY-1125",metrics:[{label:{vi:"Lương chức danh",en:"Job-title wage"},value:"12,000,000 VND"},{label:{vi:"Phụ cấp trách nhiệm",en:"Responsibility allowance"},value:"1,500,000 VND"},{label:{vi:"Tỷ lệ người lao động đóng (mô phỏng)",en:"Employee rate (simulated)"},value:"10.5%"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Từ tháng sau đăng ký đóng BHXH cho cả xưởng theo lương tối thiểu vùng thôi, phần còn lại chuyển thành ‘hỗ trợ khác’ cho nhẹ chi phí. Đừng nói với công nhân.”",en:"The plant director messages you: “From next month register everyone's social insurance at the regional minimum wage and move the rest into ‘other support’ to cut costs. Don't tell the workers.”"},options:{safe:{vi:"Từ chối đăng ký mức đóng thấp hơn tiền lương thực tế; báo Trưởng nhóm C&B và Giám đốc Nhân sự bằng văn bản, nêu rủi ro truy thu, xử phạt và đề xuất phương án tối ưu chi phí hợp pháp.",en:"Refuse to register contributions below actual wages; inform the C&B lead and HR Director in writing about back-payment and penalty risks, and propose lawful cost-saving options."},shortcut:{vi:"Chuyển phần lương thành “hỗ trợ khác” và đăng ký đóng theo lương tối thiểu vùng như yêu cầu.",en:"Relabel part of the wage as “other support” and register contributions at the minimum wage as asked."},wait:{vi:"Không làm gì, chờ phòng kế toán tự quyết định mức đóng.",en:"Do nothing and wait for Accounting to decide the contribution level."}},questions:{vi:["Vì sao phụ cấp trách nhiệm được xếp SI-INCL và khấu trừ đúng là 1.417.500 đồng? Khoản nào không tính và tại sao?","Đóng BHXH thấp hơn tiền lương thực tế gây thiệt hại gì cho người lao động và rủi ro gì cho công ty? Bạn đề xuất gì?"],en:["Why is the responsibility allowance SI-INCL, and why is the deduction VND 1,417,500? Which items are excluded and why?","How does under-declaring the contribution wage harm workers and expose the company? What do you propose?"]},hints:{vi:["So từng khoản thu nhập trên bảng lương nháp với bảng phân loại thu nhập đóng BHXH.","Cộng lương chức danh với phụ cấp lương rồi nhân tỷ lệ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mức đóng phải theo tiền lương thực tế; mọi yêu cầu khai thấp phải được báo cáo."],en:["Check each income item on the draft payroll against the contribution classification table.","Add the job-title wage and wage allowances, then apply the rate as in SOP 3.2.","Re-read SOP 4.2: contributions follow actual wages, and any request to under-declare must be escalated."]}},learning:{summary:{vi:"Chuyên viên tiền lương, phúc lợi và bảo hiểm xã hội tính lương, thưởng, thuế thu nhập cá nhân, quản lý tham gia BHXH, BHYT, BHTN, xây dựng khung lương và chính sách phúc lợi. Nghề bảo đảm người lao động được trả đúng, đủ, đúng hạn và doanh nghiệp tuân thủ pháp luật, đòi hỏi chính xác tuyệt đối, bảo mật thông tin và cập nhật quy định liên tục.",en:"A compensation and benefits specialist calculates pay, bonuses and personal income tax, manages social, health and unemployment insurance, and builds pay structures and benefit policies. The role ensures people are paid correctly, fully and on time and that the company stays compliant, and requires absolute accuracy, confidentiality and constant regulatory updates."},responsibilities:{vi:["Thu thập chấm công, tăng ca, nghỉ phép và tính lương, thưởng hằng tháng.","Tính khấu trừ BHXH, BHYT, BHTN và thuế thu nhập cá nhân, kinh phí công đoàn phía doanh nghiệp.","Lập hồ sơ tăng, giảm lao động, điều chỉnh mức đóng và giải quyết chế độ ốm đau, thai sản.","Xây dựng, cập nhật thang bảng lương, khảo sát lương thị trường và chính sách phúc lợi.","Quyết toán thuế, đối soát với kế toán và bảo mật dữ liệu tiền lương."],en:["Collect timesheets, overtime and leave and run monthly pay and bonuses.","Calculate social, health and unemployment insurance, personal income tax and the employer's union fee.","File joiner and leaver records, adjust contribution levels and process sickness and maternity benefits.","Build and update pay scales, run market pay surveys and design benefit policies.","Finalise annual tax, reconcile with Accounting and keep payroll data confidential."]},competencies:[{name:{vi:"Tính lương chính xác",en:"Payroll accuracy"},desc:{vi:"Áp đúng công thức lương, tăng ca, phụ cấp, khấu trừ và kiểm tra chéo trước khi chi trả.",en:"Apply pay, overtime, allowance and deduction rules correctly and cross-check before payment."}},{name:{vi:"Pháp luật lao động, bảo hiểm",en:"Labour & insurance law"},desc:{vi:"Nắm quy định tiền lương, BHXH, BHYT, BHTN, thuế TNCN và cập nhật thay đổi kịp thời.",en:"Know the rules on wages, social, health and unemployment insurance and income tax, and track changes."}},{name:{vi:"Thiết kế đãi ngộ",en:"Reward design"},desc:{vi:"Xây dựng khung lương theo giá trị công việc, compa-ratio và dữ liệu thị trường.",en:"Build pay bands from job value, compa-ratio and market data."}},{name:{vi:"Phân tích dữ liệu",en:"Data analysis"},desc:{vi:"Dùng bảng tính, hệ thống nhân sự để đối soát, phát hiện bất thường và báo cáo chi phí nhân sự.",en:"Use spreadsheets and HR systems to reconcile, spot anomalies and report people costs."}},{name:{vi:"Bảo mật & chính trực",en:"Confidentiality & integrity"},desc:{vi:"Giữ bí mật lương, từ chối khai sai mức đóng và báo cáo rủi ro tuân thủ.",en:"Keep pay confidential, refuse to misdeclare contributions and escalate compliance risks."}}],knowledge:{vi:["Bộ luật Lao động số 45/2019/QH14: tiền lương, làm thêm giờ (ít nhất 150% ngày thường, 200% ngày nghỉ hằng tuần, 300% ngày lễ, tết), làm việc ban đêm.","Luật Bảo hiểm xã hội số 41/2024/QH15 (hiệu lực từ 01/7/2025) và văn bản hướng dẫn về tiền lương làm căn cứ đóng.","Luật Bảo hiểm y tế và Luật Việc làm về bảo hiểm y tế, bảo hiểm thất nghiệp.","Quy định hiện hành về thuế thu nhập cá nhân: giảm trừ gia cảnh, biểu thuế lũy tiến từng phần với thu nhập từ tiền lương.","Mức lương tối thiểu vùng do Chính phủ công bố theo từng thời kỳ.","Luật Công đoàn: kinh phí công đoàn do người sử dụng lao động đóng bằng 2% quỹ tiền lương làm căn cứ đóng BHXH."],en:["Labour Code No. 45/2019/QH14: wages, overtime (at least 150% on normal days, 200% on weekly rest days, 300% on public holidays) and night work.","Social Insurance Law No. 41/2024/QH15 (effective 1 July 2025) and its guidance on the contribution wage.","The Health Insurance Law and the Employment Law on health and unemployment insurance.","Current personal income tax rules: family deductions and the progressive tax schedule for employment income.","Regional minimum wages announced by the Government from time to time.","The Trade Union Law: employers pay a union fee of 2% of the payroll used for social insurance contributions."]},tools:["Phần mềm tính lương và nhân sự (HRIS)","Hệ thống chấm công","Cổng giao dịch điện tử bảo hiểm xã hội","Phần mềm hỗ trợ quyết toán thuế TNCN","Bảng tính có công thức kiểm soát"],kpis:{vi:["Tỷ lệ phiếu lương chính xác, không phải điều chỉnh sau chi trả.","Chi trả lương đúng hạn ở 100% kỳ lương.","Hồ sơ tăng giảm lao động nộp đúng hạn, không phát sinh truy thu bảo hiểm.","Thời gian giải quyết chế độ ốm đau, thai sản cho người lao động."],en:["Share of payslips correct with no post-payment adjustment.","On-time payment in 100% of pay periods.","Joiner and leaver filings on time with no insurance back-payments.","Turnaround time for employees' sickness and maternity claims."]},day:[{time:"08:30",vi:"Chốt dữ liệu chấm công, tăng ca của các xưởng và kiểm tra bất thường.",en:"Lock timesheet and overtime data from the workshops and check anomalies."},{time:"10:00",vi:"Chạy bảng lương nháp, đối chiếu phụ cấp, khấu trừ với hồ sơ đã duyệt.",en:"Run the draft payroll and match allowances and deductions with approved records."},{time:"13:30",vi:"Lập hồ sơ tăng giảm lao động và điều chỉnh mức đóng bảo hiểm.",en:"Prepare joiner and leaver filings and adjust contribution levels."},{time:"15:00",vi:"Giải đáp thắc mắc về phiếu lương, chế độ thai sản cho người lao động.",en:"Answer employees' questions on payslips and maternity benefits."},{time:"16:30",vi:"Đối soát quỹ lương với kế toán và trình duyệt bảng lương.",en:"Reconcile the payroll fund with Accounting and submit payroll for approval."}],mistakes:{vi:["Bỏ sót phụ cấp lương khi xác định tiền lương đóng BHXH, khiến người lao động thiệt quyền lợi.","Tính tăng ca ngày nghỉ hằng tuần, ngày lễ theo hệ số ngày thường.","Đăng ký mức đóng theo lương tối thiểu vùng trong khi lương thực tế cao hơn, dẫn tới truy thu và xử phạt."],en:["Leaving wage allowances out of the contribution wage, cutting workers' entitlements.","Paying rest-day or holiday overtime at the normal-day rate.","Registering contributions at the minimum wage when actual pay is higher, leading to back-payments and penalties."]},career:[{vi:"Nhân viên tiền lương",en:"Payroll officer"},{vi:"Chuyên viên lương & phúc lợi",en:"C&B specialist"},{vi:"Trưởng nhóm lương & phúc lợi",en:"C&B team lead"},{vi:"Quản lý đãi ngộ toàn diện",en:"Total rewards manager"}],glossary:[{term:"Contribution wage",vi:"Mức lương, phụ cấp lương và khoản bổ sung trả thường xuyên làm căn cứ tính bảo hiểm bắt buộc.",en:"The wage, wage allowances and regular supplements used as the base for compulsory insurance."},{term:"Compa-ratio",vi:"Tỷ lệ giữa lương thực trả và điểm giữa của khung lương, cho biết vị trí lương trong bậc.",en:"Actual pay divided by the pay band midpoint, showing where pay sits in the band."},{term:"Gross-to-net",vi:"Quy trình tính từ tổng thu nhập trước khấu trừ ra số tiền người lao động thực nhận.",en:"The calculation from gross earnings before deductions to the employee's net pay."},{term:"Family deduction",vi:"Khoản giảm trừ cho bản thân và người phụ thuộc trước khi tính thuế TNCN từ tiền lương.",en:"The allowance for the taxpayer and dependants deducted before computing income tax on wages."},{term:"Total rewards",vi:"Tổng đãi ngộ gồm lương, thưởng, phúc lợi, cơ hội phát triển và trải nghiệm làm việc.",en:"The full package of pay, bonuses, benefits, development and work experience."}],quiz:[{q:{vi:"Lương giờ ngày thường là 100.000 đồng. Làm thêm 4 giờ vào ngày nghỉ hằng tuần, tiền làm thêm tối thiểu là bao nhiêu?",en:"The normal hourly wage is VND 100,000. What is the minimum pay for 4 overtime hours on a weekly rest day?"},options:{vi:["600.000 đồng","400.000 đồng","1.200.000 đồng","800.000 đồng"],en:["VND 600,000","VND 400,000","VND 1,200,000","VND 800,000"]},answer:3,explain:{vi:"Ngày nghỉ hằng tuần ít nhất 200%: 4 x 100.000 x 200% = 800.000 đồng.",en:"Weekly rest days pay at least 200%: 4 x 100,000 x 200% = VND 800,000."}},{q:{vi:"Khoản nào thường KHÔNG tính vào tiền lương đóng BHXH?",en:"Which item is usually NOT part of the contribution wage?"},options:{vi:["Phụ cấp trách nhiệm","Lương theo chức danh","Tiền ăn giữa ca","Phụ cấp thâm niên"],en:["Responsibility allowance","Job-title wage","Shift meal allowance","Seniority allowance"]},answer:2,explain:{vi:"Tiền ăn giữa ca là khoản phúc lợi, không tính vào tiền lương đóng; phụ cấp lương thì có tính.",en:"Shift meals are a welfare benefit outside the contribution wage; wage allowances are included."}},{q:{vi:"Giám đốc yêu cầu đóng BHXH theo lương tối thiểu vùng dù lương thực tế cao hơn. Bạn làm gì?",en:"The director asks you to pay insurance on the minimum wage although actual pay is higher. What do you do?"},options:{vi:["Từ chối, báo cáo bằng văn bản và đề xuất phương án hợp pháp","Làm theo vì là chỉ đạo","Chỉ áp dụng cho công nhân mới","Làm theo nhưng không lưu email"],en:["Refuse, report in writing and propose lawful options","Comply because it is an order","Apply it only to new workers","Comply but delete the email"]},answer:0,explain:{vi:"Khai thấp mức đóng làm người lao động thiệt quyền lợi và doanh nghiệp bị truy thu, xử phạt.",en:"Under-declaring cuts workers' benefits and exposes the company to back-payments and penalties."}},{q:{vi:"Kinh phí công đoàn do người sử dụng lao động đóng bằng bao nhiêu?",en:"How much is the union fee paid by the employer?"},options:{vi:["1% quỹ lương","2% quỹ tiền lương làm căn cứ đóng BHXH","0.5% lương cơ sở","3% quỹ thưởng"],en:["1% of payroll","2% of the payroll used for social insurance","0.5% of the base salary","3% of the bonus pool"]},answer:1,explain:{vi:"Theo Luật Công đoàn, mức đóng là 2% quỹ tiền lương làm căn cứ đóng BHXH cho người lao động.",en:"Under the Trade Union Law the fee is 2% of the payroll used as the social insurance base."}}],tools_en:["Payroll and HR software (HRIS)","Time and attendance system","Social insurance e-transaction portal","Personal income tax finalization software","Spreadsheets with control formulas"]}}})})(window.KKR);
